SELECT s.*
FROM act_signup s
WHERE s.deleted = 0
  AND s.activity_id = #{activityId}

    AND s.status = #{status}

ORDER BY s.signup_time DESC, s.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM act_signup s
WHERE s.deleted = 0
  AND s.activity_id = #{activityId}

    AND s.status = #{status}
